    $detailRoute = $role === 'admin' ? 'admin.booking-cuci.show' : 'petugas.booking-cuci.show';
    $actionRoute = $role === 'admin' ? 'admin.booking-cuci.action' : 'petugas.booking-cuci.action';
    $statusLabels = ['menunggu'=>'Menunggu','diterima'=>'Dikonfirmasi','proses'=>'Diproses','selesai'=>'Selesai','dibatalkan'=>'Dibatalkan'];
    $statusTone = ['menunggu'=>'warning','diterima'=>'info','proses'=>'info','selesai'=>'success','dibatalkan'=>'danger'];
    $money = fn($value) => 'Rp '.number_format((float)$value,0,',','.');
    $vehicleImage = function($vehicle) {
        if (!$vehicle) return asset('assets/images/vehicles/avanza/gray/front.png');
        foreach (array_filter([
            \Illuminate\Support\Str::slug(trim(($vehicle->merk ?? '').' '.($vehicle->model ?? ''))),
            \Illuminate\Support\Str::slug((string)($vehicle->model ?? '')),
        ]) as $slug) {
            $matches = glob(public_path('assets/images/vehicles/'.$slug.'/*/front.png')) ?: [];
            if ($matches) return asset(str_replace('\\','/',substr($matches[0],strlen(public_path())+1)));
        }
        return asset('assets/images/vehicles/avanza/gray/front.png');
    };
@endphp
